+
+func TestEncodeJSONKeepsHTMLAndDropsFinalNewline(t *testing.T) {
+	got, err := EncodeJSON(map[string]string{"html": "<b>Tom & Jerry</b>"})
+	if err != nil {
+		t.Fatalf("EncodeJSON returned error: %v", err)
+	}
+	want := `{"html":"<b>Tom & Jerry</b>"}`
+	if string(got) != want {
+		t.Errorf("EncodeJSON = %q, want %q", got, want)
+	}
+}
+
+func TestEncodeJSONReturnsEncodingError(t *testing.T) {
+	got, err := EncodeJSON(make(chan int))
+	if err == nil {
+		t.Fatalf("EncodeJSON(chan) = %q, nil error, want an error", got)
+	}
+}

